package com.school.management.entity; import jakarta.persistence.*;import java.time.LocalDate;
@Entity public class Attendance { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private Long studentId; private LocalDate date; private String status; private String remarks; public Attendance(){} public Long getId(){return id;} public Long getStudentId(){return studentId;} public void setStudentId(Long v){studentId=v;} public LocalDate getDate(){return date;} public void setDate(LocalDate v){date=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} public String getRemarks(){return remarks;} public void setRemarks(String v){remarks=v;} }
